import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"SearchPanel","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/search-panel.md","filePath":"workbench/search-panel.md"}'),n={name:"workbench/search-panel.md"};function r(s,e,h,c,i,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="searchpanel" tabindex="-1">SearchPanel <a class="header-anchor" href="#searchpanel" aria-label="Permalink to &quot;SearchPanel&quot;">​</a></h1><p>SearchPanel is a panel that finds things: an input, then the results in groups.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it to find anything the application can list by name: the things on the stage, the pages, the commands. The application passes the results in groups and decides what a pick does; the panel knows nothing of what is found. For a short list that is already at hand, let the panel filter it (the default). For a search that runs elsewhere, pass <code>filter={false}</code>, search on <code>onquery</code> and pass the results back in <code>groups</code>. An input alone, without results of its own, is a <a href="./../components/search-input">SearchInput</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>groups</code></td><td>required</td><td>The results, <code>{ label, items: SearchItem[] }[]</code></td></tr><tr><td><code>query</code></td><td><code>&#39;&#39;</code></td><td>The query in the input (bindable)</td></tr><tr><td><code>onquery</code></td><td></td><td>Called with the query on every key stroke</td></tr><tr><td><code>onpick</code></td><td></td><td>Called with the id of the result that is pressed</td></tr><tr><td><code>filter</code></td><td><code>true</code></td><td>Keep the results that contain the query</td></tr><tr><td><code>title</code></td><td><code>search</code> message</td><td>The title in the head and the name of the input</td></tr><tr><td><code>placeholder</code></td><td></td><td>The faint text in the empty input</td></tr><tr><td><code>empty</code></td><td><code>noMatches</code> message</td><td>What shows when the query has no result</td></tr><tr><td><code>hint</code></td><td></td><td>What shows while the query is empty and nothing shows</td></tr><tr><td><code>onclose</code></td><td></td><td>Shows a close button in the head</td></tr><tr><td><code>side</code></td><td><code>panel</code></td><td>The width, as <a href="./../components/panel">Panel</a>&#39;s <code>side</code></td></tr></tbody></table><p>A <code>SearchItem</code> is <code>{ id, label, hint?, icon? }</code>: <code>hint</code> is a second line under the name, and <code>icon</code> an icon name or component.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A <a href="./../components/panel">Panel</a> with a <a href="./../components/toolbar">Toolbar</a> as its head. The content starts with the <a href="./../components/search-input">SearchInput</a> in a <a href="./../components/block">Block</a>; each group that has results follows as a <a href="./../components/section-header">SectionHeader</a> over a <a href="./../components/list">List</a>, and each result is a pressable <a href="./../components/list-item">ListItem</a> with its icon, its name and its hint on one line each. With <code>filter</code>, a result stays when its name or its hint contains the query, ignoring case, and a group left empty is hidden. Enter in the input picks the first result and Escape clears the query. When nothing shows, a <a href="./../components/state">State</a> says <code>empty</code> for a query, or <code>hint</code> while the query is empty.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/search-panel/" title="SearchPanel" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/search-panel/" target="_blank" rel="noopener">SearchPanel</a></figcaption></figure>',11)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
